CREATE OR REPLACE FUNCTION public.cancelar_cita_publica(p_slug text, p_cita_id uuid, p_telefono text, p_motivo text DEFAULT NULL::text, p_canal text DEFAULT 'web'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_negocio text;
  v_cita    record;
  v_horas   int;
  v_fuera   boolean;
begin
  select negocio_id into v_negocio
  from public.negocio_portal
  where slug = p_slug and portal_activo = true;
  if v_negocio is null then raise exception 'Portal no disponible'; end if;

  select c.id, c.estado, c.inicio, coalesce(s.cancelacion_horas, 24) as cancelacion_horas
    into v_cita
  from public.citas c
  join public.clientes cl on cl.id = c.cliente_id
  left join public.servicios s on s.id = c.servicio_id
  where c.id = p_cita_id and c.negocio_id = v_negocio
    and public.normalizar_telefono(cl.telefono) = public.normalizar_telefono(p_telefono);
  if v_cita.id is null then raise exception 'Cita no encontrada'; end if;
  if v_cita.estado not in ('pendiente','confirmada') then raise exception 'La cita no se puede cancelar'; end if;
  if v_cita.inicio <= now() then raise exception 'La cita ya ha pasado'; end if;

  v_horas := v_cita.cancelacion_horas;
  v_fuera := v_cita.inicio < now() + make_interval(hours => v_horas);

  update public.citas
    set estado = 'cancelada',
        cancelado_por = case when coalesce(nullif(trim(p_canal),''),'web') in ('web','whatsapp','agente_voz','asistente_ia') then p_canal else 'web' end,
        motivo_cancelacion = left(nullif(trim(p_motivo), ''), 300),
        modificado_at = now()
  where id = p_cita_id;

  return jsonb_build_object(
    'ok', true,
    'cita_id', p_cita_id,
    'estado', 'cancelada',
    'fuera_de_plazo', v_fuera,
    'cancelacion_horas', v_horas
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.crear_cita_publica(p_slug text, p_servicio_id uuid, p_profesional_id uuid, p_inicio timestamp with time zone, p_nombre text, p_telefono text, p_email text DEFAULT NULL::text, p_notas text DEFAULT NULL::text, p_consiente_ia boolean DEFAULT false, p_captcha_token text DEFAULT NULL::text, p_canal text DEFAULT 'web'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_negocio text; v_dur int; v_espera int; v_extra int; v_total int; v_min_ant int;
  v_precio numeric; v_prepago boolean; v_prepago_pct numeric; v_prepago_fijo numeric;
  v_cliente uuid; v_cita uuid; v_fin timestamptz; v_fin_activa timestamptz; v_fin_espera timestamptz;
  v_deposito numeric := 0; v_estado text; v_canal text; v_tz text := 'Europe/Madrid';
  v_nivel_sin_deposito boolean := false;
  v_ip text;
  v_captcha_exigido boolean := false;
  v_tel_clean text;
begin
  v_canal := case when p_canal in ('web','whatsapp','agente_voz','asistente_ia') then p_canal else 'web' end;

  select negocio_id, coalesce(captcha_activo, false)
    into v_negocio, v_captcha_exigido
  from public.negocio_portal
  where slug = p_slug and portal_activo = true;

  if v_negocio is null then raise exception 'Portal no disponible'; end if;

  -- Gate de suscripcion: salon caducado o sin acceso
  if not public.negocio_con_acceso(v_negocio) then
    raise exception 'El servicio de reserva online no esta disponible temporalmente para este salon. Por favor, contacta directamente con el establecimiento.';
  end if;

  -- Rate Limiting por IP para canal web (max 5 peticiones por minuto)
  if v_canal = 'web' then
    v_ip := public.request_ip();
    if not public.rate_limit_ok('crear_cita_publica_ip', v_ip, 5, interval '1 minute') then
      raise exception 'Demasiados intentos desde esta conexión. Por favor, espera un minuto o contacta con el salón.';
    end if;
  end if;

  -- Validación de Captcha de un solo uso
  if p_captcha_token is not null and length(trim(p_captcha_token)) > 0 then
    if not public.consumir_captcha_token(p_captcha_token) then
      raise exception 'La verificación de seguridad ha caducado o no es válida. Por favor, inténtalo de nuevo.';
    end if;
  end if;

  if exists (select 1 from public.cierres_negocio cn
      where cn.negocio_id = v_negocio and cn.fecha = (p_inicio at time zone v_tz)::date) then
    raise exception 'El salon esta cerrado ese dia';
  end if;

  if coalesce(length(trim(p_nombre)), 0) < 2 then raise exception 'Indica tu nombre.'; end if;

  -- Validación y normalización de teléfono
  v_tel_clean := regexp_replace(coalesce(p_telefono, ''), '\D', '', 'g');
  if coalesce(length(public.normalizar_telefono(p_telefono)), 0) < 7 or length(v_tel_clean) < 8 then
    raise exception 'Indica un teléfono móvil válido para la confirmación de la cita.';
  end if;

  select duracion_activa_min, coalesce(duracion_espera_min,0), coalesce(duracion_activa_extra_min,0),
         coalesce(min_antelacion_min,0), precio, coalesce(prepago_requerido,false), prepago_porcentaje, prepago_cantidad_fija
    into v_dur, v_espera, v_extra, v_min_ant, v_precio, v_prepago, v_prepago_pct, v_prepago_fijo
  from public.servicios
  where id = p_servicio_id and negocio_id = v_negocio and reservable_online = true and activo = true;

  if v_dur is null then raise exception 'Servicio no reservable'; end if;

  if not exists (select 1 from public.profesionales where id = p_profesional_id and negocio_id = v_negocio and activo = true)
  then raise exception 'Profesional no valido'; end if;

  -- Override activo = false: ese profesional no realiza este servicio.
  if not public.profesional_ofrece_servicio(p_profesional_id, p_servicio_id) then
    raise exception 'Ese profesional no realiza este servicio';
  end if;

  -- Duracion efectiva: override del profesional por encima del catalogo.
  select d.activa, d.espera, d.extra
    into v_dur, v_espera, v_extra
  from public.duracion_efectiva_profesional(p_servicio_id, p_profesional_id, v_dur, v_espera, v_extra) d;

  if exists (select 1 from public.clientes where negocio_id = v_negocio
      and public.normalizar_telefono(telefono) = public.normalizar_telefono(p_telefono) and bloqueado = true) then
    raise exception 'No es posible completar la reserva online con estos datos. Por favor, contacta directamente con el salon.';
  end if;

  if (select count(*) from public.citas c join public.clientes cl on cl.id = c.cliente_id
      where c.negocio_id = v_negocio and public.normalizar_telefono(cl.telefono) = public.normalizar_telefono(p_telefono)
        and c.estado in ('pendiente','confirmada') and c.inicio > now()) >= 3 then
    raise exception 'Ya tienes varias citas pendientes. Para mas reservas, contacta con el salon.';
  end if;

  if v_canal = 'web' and (select count(*) from public.citas where negocio_id = v_negocio and canal = 'web' and created_at > now() - interval '1 hour') >= 30 then
    raise exception 'La reserva online no esta disponible en este momento. Llama al salon, por favor.';
  end if;

  v_total := v_dur + v_espera + v_extra;
  v_fin_activa := p_inicio + make_interval(mins => v_dur);
  v_fin_espera := p_inicio + make_interval(mins => v_dur + v_espera);
  v_fin := p_inicio + make_interval(mins => v_total);

  if p_inicio < now() + make_interval(mins => greatest(v_min_ant, 0)) then raise exception 'Fuera de la antelacion minima'; end if;

  if not exists (select 1 from public.horarios_profesional h where h.profesional_id = p_profesional_id
      and h.dia_semana = extract(dow from (p_inicio at time zone v_tz))::int
      and (p_inicio at time zone v_tz)::time >= h.hora_inicio and (v_fin at time zone v_tz)::time <= h.hora_fin)
  then raise exception 'Fuera del horario laboral'; end if;

  -- Comprobación respetando huecos de reposo químico (no solapar fase activa ni extra)
  if exists (
    select 1 from public.citas c
    cross join lateral public.ventanas_activas_cita(c.id, c.inicio, c.fin_activa, c.fin_espera, c.fin) v
    where c.profesional_id = p_profesional_id
      and c.estado in ('pendiente','confirmada')
      and v.desde < v_fin
      and v.hasta > p_inicio
  ) then raise exception 'El hueco ya esta ocupado'; end if;

  if exists (select 1 from public.bloqueos_profesional b where b.profesional_id = p_profesional_id
      and b.inicio < v_fin and b.fin > p_inicio) then raise exception 'El profesional no esta disponible'; end if;

  select id into v_cliente from public.clientes where negocio_id = v_negocio
    and public.normalizar_telefono(telefono) = public.normalizar_telefono(p_telefono) limit 1;

  if v_cliente is null then
    insert into public.clientes (
      negocio_id, nombre, telefono, email,
      consiente_ia, consiente_ia_origen, consiente_ia_fecha
    )
    values (
      v_negocio,
      left(trim(p_nombre), 120),
      trim(p_telefono),
      left(nullif(trim(p_email), ''), 200),
      p_consiente_ia,
      case when p_consiente_ia then 'portal' else null end,
      case when p_consiente_ia then now() else null end
    )
    returning id into v_cliente;
  else
    update public.clientes
       set consiente_ia = p_consiente_ia,
           consiente_ia_origen = 'portal',
           consiente_ia_fecha = now()
     where id = v_cliente
       and (consiente_ia is distinct from p_consiente_ia or consiente_ia_origen is null);
  end if;

  v_nivel_sin_deposito := coalesce((public.obtener_nivel_cliente(v_cliente)->'nivel'->>'sin_deposito')::boolean, false);

  if v_nivel_sin_deposito then
    v_deposito := 0;
  else
    if v_prepago then
      if v_prepago_fijo is not null and v_prepago_fijo > 0 then v_deposito := v_prepago_fijo;
      elsif v_prepago_pct is not null and v_prepago_pct > 0 then v_deposito := round(coalesce(v_precio, 0) * v_prepago_pct / 100.0, 2);
      end if;
    end if;

    if coalesce((select (config->>'depositoDinamicoActivo')::boolean from public.negocio_config where negocio_id = v_negocio), false) then
      declare v_tier text; v_factor numeric; v_uf int; v_ua int;
      begin
        select coalesce((config->>'depositoFactorRiesgo')::numeric, 2), coalesce((config->>'depositoUmbralFiableCompletadas')::int, 3), coalesce((config->>'depositoUmbralAltoNoShows')::int, 2)
          into v_factor, v_uf, v_ua from public.negocio_config where negocio_id = v_negocio;
        v_tier := public.perfil_riesgo_cliente(v_cliente, coalesce(v_uf,3), coalesce(v_ua,2));
        if v_tier = 'exento' then v_deposito := 0;
        elsif v_tier = 'riesgo' then v_deposito := least(round(v_deposito * coalesce(v_factor,2), 2), coalesce(v_precio,0));
        elsif v_tier = 'alto' then v_deposito := coalesce(v_precio, 0);
        end if;
      end;
    end if;
  end if;

  v_estado := case when v_deposito > 0 then 'pendiente' else 'confirmada' end;

  insert into public.citas (negocio_id, profesional_id, servicio_id, cliente_id, inicio, fin, fin_activa, fin_espera,
    estado, canal, notas, deposito_requerido, deposito_pagado, deposito_importe, confirmado_por_cliente,
    consentimiento_datos, consentimiento_at)
  values (v_negocio, p_profesional_id, p_servicio_id, v_cliente, p_inicio, v_fin, v_fin_activa, v_fin_espera,
    v_estado, v_canal, left(nullif(trim(p_notas), ''), 500), (v_deposito > 0), false, nullif(v_deposito, 0), true,
    true, now())
  returning id into v_cita;

  return jsonb_build_object('cita_id', v_cita, 'cliente_id', v_cliente, 'estado', v_estado, 'canal', v_canal,
    'deposito_requerido', (v_deposito > 0), 'deposito_importe', v_deposito, 'inicio', p_inicio, 'fin', v_fin);
end;
$function$

CREATE OR REPLACE FUNCTION public.crear_cita_publica_cadena(p_slug text, p_servicio_ids uuid[], p_profesional_id uuid, p_inicio timestamp with time zone, p_nombre text, p_telefono text, p_email text DEFAULT NULL::text, p_notas text DEFAULT NULL::text, p_consiente_ia boolean DEFAULT false, p_captcha_token text DEFAULT NULL::text, p_canal text DEFAULT 'web'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_negocio text; v_tz text := 'Europe/Madrid'; v_canal text;
  v_ip text; v_tel_clean text;
  v_cliente uuid; v_grupo uuid := gen_random_uuid();
  v_cursor timestamptz; v_fin_cadena timestamptz;
  v_precio_total numeric := 0; v_deposito numeric := 0; v_estado text;
  v_nivel_sin_deposito boolean := false;
  v_primera uuid := null; v_orden int := 0;
  v_sid uuid;
  v_dur int; v_espera int; v_extra int; v_min_ant int;
  v_precio numeric; v_prepago boolean; v_prepago_pct numeric; v_prepago_fijo numeric;
  v_fin_activa timestamptz; v_fin_espera timestamptz; v_fin timestamptz;
  v_cita uuid;
  v_tramos jsonb := '[]'::jsonb;
begin
  if p_servicio_ids is null or array_length(p_servicio_ids, 1) is null then
    raise exception 'Indica al menos un servicio.';
  end if;
  if array_length(p_servicio_ids, 1) > 4 then
    raise exception 'Demasiados servicios en una misma reserva. Llama al salon, por favor.';
  end if;

  v_canal := case when p_canal in ('web','whatsapp','agente_voz','asistente_ia') then p_canal else 'web' end;

  select negocio_id into v_negocio
    from public.negocio_portal
   where slug = p_slug and portal_activo = true;
  if v_negocio is null then raise exception 'Portal no disponible'; end if;

  if v_canal = 'web' then
    v_ip := public.request_ip();
    if not public.rate_limit_ok('crear_cita_publica_ip', v_ip, 5, interval '1 minute') then
      raise exception 'Demasiados intentos desde esta conexión. Por favor, espera un minuto o contacta con el salón.';
    end if;
  end if;

  if p_captcha_token is not null and length(trim(p_captcha_token)) > 0 then
    if not public.consumir_captcha_token(p_captcha_token) then
      raise exception 'La verificación de seguridad ha caducado o no es válida. Por favor, inténtalo de nuevo.';
    end if;
  end if;

  if exists (select 1 from public.cierres_negocio cn
      where cn.negocio_id = v_negocio and cn.fecha = (p_inicio at time zone v_tz)::date) then
    raise exception 'El salon esta cerrado ese dia';
  end if;

  if coalesce(length(trim(p_nombre)), 0) < 2 then raise exception 'Indica tu nombre.'; end if;

  v_tel_clean := regexp_replace(coalesce(p_telefono, ''), '[^0-9]', '', 'g');
  if coalesce(length(public.normalizar_telefono(p_telefono)), 0) < 7 or length(v_tel_clean) < 8 then
    raise exception 'Indica un teléfono móvil válido para la confirmación de la cita.';
  end if;

  if not exists (select 1 from public.profesionales
                  where id = p_profesional_id and negocio_id = v_negocio and activo = true) then
    raise exception 'Profesional no valido';
  end if;

  if exists (select 1 from public.clientes where negocio_id = v_negocio
      and public.normalizar_telefono(telefono) = public.normalizar_telefono(p_telefono)
      and bloqueado = true) then
    raise exception 'No es posible completar la reserva online con estos datos. Por favor, contacta directamente con el salon.';
  end if;

  if (select count(*) from public.citas c join public.clientes cl on cl.id = c.cliente_id
      where c.negocio_id = v_negocio
        and public.normalizar_telefono(cl.telefono) = public.normalizar_telefono(p_telefono)
        and c.estado in ('pendiente','confirmada') and c.inicio > now()) >= 3 then
    raise exception 'Ya tienes varias citas pendientes. Para mas reservas, contacta con el salon.';
  end if;

  if v_canal = 'web' and (select count(*) from public.citas
                           where negocio_id = v_negocio and canal = 'web'
                             and created_at > now() - interval '1 hour') >= 30 then
    raise exception 'La reserva online no esta disponible en este momento. Llama al salon, por favor.';
  end if;

  v_cursor := p_inicio;
  foreach v_sid in array p_servicio_ids loop
    select duracion_activa_min, coalesce(duracion_espera_min,0), coalesce(duracion_activa_extra_min,0),
           coalesce(min_antelacion_min,0), precio
      into v_dur, v_espera, v_extra, v_min_ant, v_precio
      from public.servicios
     where id = v_sid and negocio_id = v_negocio and reservable_online = true and activo = true;
    if v_dur is null then raise exception 'Servicio no reservable'; end if;

    if not public.profesional_ofrece_servicio(p_profesional_id, v_sid) then
      raise exception 'Ese profesional no realiza uno de los servicios elegidos';
    end if;

    select d.activa, d.espera, d.extra into v_dur, v_espera, v_extra
      from public.duracion_efectiva_profesional(v_sid, p_profesional_id, v_dur, v_espera, v_extra) d;

    if v_cursor = p_inicio and p_inicio < now() + make_interval(mins => greatest(v_min_ant, 0)) then
      raise exception 'Fuera de la antelacion minima';
    end if;

    v_fin := v_cursor + make_interval(mins => v_dur + v_espera + v_extra);

    if not exists (select 1 from public.horarios_profesional h
                    where h.profesional_id = p_profesional_id
                      and h.dia_semana = extract(dow from (v_cursor at time zone v_tz))::int
                      and (v_cursor at time zone v_tz)::time >= h.hora_inicio
                      and (v_fin at time zone v_tz)::time <= h.hora_fin) then
      raise exception 'La reserva completa no cabe en el horario de ese profesional';
    end if;

    if exists (
      select 1 from public.citas c
       cross join lateral public.ventanas_activas_cita(c.id, c.inicio, c.fin_activa, c.fin_espera, c.fin) v
       where c.profesional_id = p_profesional_id
         and c.estado in ('pendiente','confirmada')
         and v.desde < v_fin
         and v.hasta > v_cursor
    ) then raise exception 'El hueco ya esta ocupado'; end if;

    if exists (select 1 from public.bloqueos_profesional b
                where b.profesional_id = p_profesional_id and b.inicio < v_fin and b.fin > v_cursor) then
      raise exception 'El profesional no esta disponible';
    end if;

    v_precio_total := v_precio_total + coalesce(v_precio, 0);
    v_cursor := v_fin;
  end loop;
  v_fin_cadena := v_cursor;

  select id into v_cliente from public.clientes
   where negocio_id = v_negocio
     and public.normalizar_telefono(telefono) = public.normalizar_telefono(p_telefono) limit 1;

  if v_cliente is null then
    insert into public.clientes (negocio_id, nombre, telefono, email,
      consiente_ia, consiente_ia_origen, consiente_ia_fecha)
    values (v_negocio, left(trim(p_nombre), 120), trim(p_telefono),
      left(nullif(trim(p_email), ''), 200), p_consiente_ia,
      case when p_consiente_ia then 'portal' else null end,
      case when p_consiente_ia then now() else null end)
    returning id into v_cliente;
  else
    update public.clientes
       set consiente_ia = p_consiente_ia, consiente_ia_origen = 'portal', consiente_ia_fecha = now()
     where id = v_cliente
       and (consiente_ia is distinct from p_consiente_ia or consiente_ia_origen is null);
  end if;

  v_nivel_sin_deposito := coalesce(
    (public.obtener_nivel_cliente(v_cliente)->'nivel'->>'sin_deposito')::boolean, false);

  if not v_nivel_sin_deposito then
    select bool_or(coalesce(prepago_requerido,false)),
           max(prepago_porcentaje), max(prepago_cantidad_fija)
      into v_prepago, v_prepago_pct, v_prepago_fijo
      from public.servicios where id = any(p_servicio_ids);

    if v_prepago then
      if v_prepago_fijo is not null and v_prepago_fijo > 0 then
        v_deposito := v_prepago_fijo;
      elsif v_prepago_pct is not null and v_prepago_pct > 0 then
        v_deposito := round(v_precio_total * v_prepago_pct / 100.0, 2);
      end if;
    end if;

    if coalesce((select (config->>'depositoDinamicoActivo')::boolean
                   from public.negocio_config where negocio_id = v_negocio), false) then
      declare v_tier text; v_factor numeric; v_uf int; v_ua int;
      begin
        select coalesce((config->>'depositoFactorRiesgo')::numeric, 2),
               coalesce((config->>'depositoUmbralFiableCompletadas')::int, 3),
               coalesce((config->>'depositoUmbralAltoNoShows')::int, 2)
          into v_factor, v_uf, v_ua
          from public.negocio_config where negocio_id = v_negocio;
        v_tier := public.perfil_riesgo_cliente(v_cliente, coalesce(v_uf,3), coalesce(v_ua,2));
        if v_tier = 'exento' then v_deposito := 0;
        elsif v_tier = 'riesgo' then
          v_deposito := least(round(v_deposito * coalesce(v_factor,2), 2), v_precio_total);
        elsif v_tier = 'alto' then v_deposito := v_precio_total;
        end if;
      end;
    end if;
  end if;

  v_estado := case when v_deposito > 0 then 'pendiente' else 'confirmada' end;

  v_cursor := p_inicio;
  foreach v_sid in array p_servicio_ids loop
    select duracion_activa_min, coalesce(duracion_espera_min,0), coalesce(duracion_activa_extra_min,0)
      into v_dur, v_espera, v_extra
      from public.servicios where id = v_sid;
    select d.activa, d.espera, d.extra into v_dur, v_espera, v_extra
      from public.duracion_efectiva_profesional(v_sid, p_profesional_id, v_dur, v_espera, v_extra) d;

    v_fin_activa := v_cursor + make_interval(mins => v_dur);
    v_fin_espera := v_cursor + make_interval(mins => v_dur + v_espera);
    v_fin        := v_cursor + make_interval(mins => v_dur + v_espera + v_extra);

    insert into public.citas (negocio_id, profesional_id, servicio_id, cliente_id, inicio, fin,
      fin_activa, fin_espera, estado, canal, notas, deposito_requerido, deposito_pagado,
      deposito_importe, confirmado_por_cliente, consentimiento_datos, consentimiento_at,
      grupo_id, orden_en_grupo)
    values (v_negocio, p_profesional_id, v_sid, v_cliente, v_cursor, v_fin,
      v_fin_activa, v_fin_espera, v_estado, v_canal,
      case when v_orden = 0 then left(nullif(trim(p_notas), ''), 500) else null end,
      (v_orden = 0 and v_deposito > 0), false,
      case when v_orden = 0 then nullif(v_deposito, 0) else null end,
      true, true, now(), v_grupo, v_orden)
    returning id into v_cita;

    if v_primera is null then v_primera := v_cita; end if;
    v_tramos := v_tramos || jsonb_build_object('cita_id', v_cita, 'servicio_id', v_sid,
                                               'inicio', v_cursor, 'fin', v_fin);
    v_orden := v_orden + 1;
    v_cursor := v_fin;
  end loop;

  return jsonb_build_object(
    'cita_id', v_primera, 'grupo_id', v_grupo, 'cliente_id', v_cliente,
    'estado', v_estado, 'canal', v_canal, 'tramos', v_tramos,
    'deposito_requerido', (v_deposito > 0), 'deposito_importe', v_deposito,
    'precio_total', v_precio_total, 'inicio', p_inicio, 'fin', v_fin_cadena);
end;
$function$

CREATE OR REPLACE FUNCTION public.crear_cita_publica_grupo(p_slug text, p_inicio timestamp with time zone, p_reservante_nombre text, p_reservante_telefono text, p_reservante_email text, p_asistentes jsonb, p_consentimiento_datos boolean DEFAULT true, p_captcha_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_negocio text;
  v_grupo uuid := gen_random_uuid();
  v_cliente uuid;
  v_asistente jsonb;
  v_orden smallint := 0;
  v_cita_id uuid;
  v_result jsonb := '[]'::jsonb;
  v_dur int; v_espera int; v_extra int; v_min_ant int;
  v_fin timestamptz; v_fin_activa timestamptz; v_fin_espera timestamptz;
  v_servicio_id uuid; v_prof_id uuid; v_asist_nombre text; v_asist_notas text;
  v_tz text := 'Europe/Madrid';
  v_n int;
begin
  if not coalesce(p_consentimiento_datos, false) then
    raise exception 'Debes aceptar el tratamiento de datos para reservar.';
  end if;

  select negocio_id into v_negocio from public.negocio_portal where slug = p_slug and portal_activo = true;
  if v_negocio is null then raise exception 'Portal no disponible'; end if;

  if exists (select 1 from public.cierres_negocio cn
      where cn.negocio_id = v_negocio and cn.fecha = (p_inicio at time zone v_tz)::date) then
    raise exception 'El salon esta cerrado ese dia';
  end if;

  if coalesce(length(trim(p_reservante_nombre)), 0) < 2 then raise exception 'Indica tu nombre.'; end if;
  if coalesce(length(trim(p_reservante_telefono)), 0) < 6 then raise exception 'Indica un telefono valido.'; end if;

  if jsonb_typeof(p_asistentes) <> 'array' then raise exception 'Formato de asistentes invalido'; end if;
  v_n := jsonb_array_length(p_asistentes);
  if v_n < 1 then raise exception 'Añade al menos un asistente'; end if;
  if v_n > 6 then raise exception 'Máximo 6 asistentes por reserva de grupo'; end if;

  if exists (select 1 from public.clientes where negocio_id = v_negocio
      and public.normalizar_telefono(telefono) = public.normalizar_telefono(p_reservante_telefono) and bloqueado = true) then
    raise exception 'No es posible completar la reserva con estos datos. Contacta con el salon.';
  end if;

  if (select count(*) from public.citas c join public.clientes cl on cl.id = c.cliente_id
      where c.negocio_id = v_negocio and public.normalizar_telefono(cl.telefono) = public.normalizar_telefono(p_reservante_telefono)
        and c.estado in ('pendiente','confirmada') and c.inicio > now()) + v_n > 6 then
    raise exception 'Ya tienes muchas citas pendientes. Contacta con el salon para gestionar el grupo.';
  end if;

  if (select count(*) from public.citas where negocio_id = v_negocio and canal = 'web'
      and created_at > now() - interval '1 hour') + v_n >= 40 then
    raise exception 'La reserva online no esta disponible en este momento. Llama al salon, por favor.';
  end if;

  select id into v_cliente from public.clientes where negocio_id = v_negocio
    and public.normalizar_telefono(telefono) = public.normalizar_telefono(p_reservante_telefono) limit 1;
  if v_cliente is null then
    insert into public.clientes (negocio_id, nombre, telefono, email)
    values (v_negocio, left(trim(p_reservante_nombre), 120), trim(p_reservante_telefono),
            left(nullif(trim(p_reservante_email), ''), 200))
    returning id into v_cliente;
  end if;

  for v_asistente in select value from jsonb_array_elements(p_asistentes) loop
    v_orden := v_orden + 1;
    v_asist_nombre := left(trim(coalesce(v_asistente->>'nombre', '')), 120);
    v_servicio_id := (v_asistente->>'servicio_id')::uuid;
    v_prof_id := (v_asistente->>'profesional_id')::uuid;
    v_asist_notas := left(nullif(trim(coalesce(v_asistente->>'notas', '')), ''), 500);

    if v_asist_nombre = '' then raise exception 'Falta el nombre del asistente %', v_orden; end if;

    select duracion_activa_min, coalesce(duracion_espera_min,0), coalesce(duracion_activa_extra_min,0),
           coalesce(min_antelacion_min,0)
      into v_dur, v_espera, v_extra, v_min_ant
    from public.servicios
    where id = v_servicio_id and negocio_id = v_negocio and reservable_online = true and activo = true;
    if v_dur is null then raise exception 'Servicio no reservable para el asistente %', v_orden; end if;

    if not exists (select 1 from public.profesionales where id = v_prof_id and negocio_id = v_negocio and activo = true) then
      raise exception 'Profesional no valido para el asistente %', v_orden;
    end if;

    -- Override activo = false: ese profesional no realiza este servicio.
    if not public.profesional_ofrece_servicio(v_prof_id, v_servicio_id) then
      raise exception 'El profesional del asistente % no realiza ese servicio', v_orden;
    end if;

    -- Duracion efectiva: override del profesional por encima del catalogo.
    select d.activa, d.espera, d.extra
      into v_dur, v_espera, v_extra
    from public.duracion_efectiva_profesional(v_servicio_id, v_prof_id, v_dur, v_espera, v_extra) d;

    v_fin_activa := p_inicio + make_interval(mins => v_dur);
    v_fin_espera := p_inicio + make_interval(mins => v_dur + v_espera);
    v_fin := p_inicio + make_interval(mins => v_dur + v_espera + v_extra);

    if p_inicio < now() + make_interval(mins => greatest(v_min_ant, 0)) then
      raise exception 'Fuera de la antelacion minima';
    end if;

    if not exists (select 1 from public.horarios_profesional h where h.profesional_id = v_prof_id
        and h.dia_semana = extract(dow from (p_inicio at time zone v_tz))::int
        and (p_inicio at time zone v_tz)::time >= h.hora_inicio and (v_fin at time zone v_tz)::time <= h.hora_fin) then
      raise exception 'Fuera del horario laboral del profesional del asistente %', v_orden;
    end if;

    if exists (
      select 1 from public.citas c
      cross join lateral public.ventanas_activas_cita(c.id, c.inicio, c.fin_activa, c.fin_espera, c.fin) v
      where c.profesional_id = v_prof_id
        and c.estado in ('pendiente','confirmada')
        and v.desde < v_fin
        and v.hasta > p_inicio
    ) then
      raise exception 'El hueco del asistente % ya esta ocupado', v_orden;
    end if;

    if exists (select 1 from public.bloqueos_profesional b where b.profesional_id = v_prof_id
        and b.inicio < v_fin and b.fin > p_inicio) then
      raise exception 'Profesional no disponible en el asistente %', v_orden;
    end if;

    insert into public.citas (
      negocio_id, profesional_id, servicio_id, cliente_id, inicio, fin, fin_activa, fin_espera,
      estado, canal, notas, deposito_requerido, deposito_pagado, confirmado_por_cliente,
      grupo_id, orden_en_grupo
    ) values (
      v_negocio, v_prof_id, v_servicio_id,
      case when v_orden = 1 then v_cliente else null end,
      p_inicio, v_fin, v_fin_activa, v_fin_espera,
      'confirmada', 'web',
      trim(concat('Grupo ', v_orden, '/', v_n, ' — ', v_asist_nombre,
                  case when v_asist_notas is not null then E'\n' || v_asist_notas else '' end)),
      false, false, true,
      v_grupo, v_orden
    ) returning id into v_cita_id;

    v_result := v_result || jsonb_build_array(jsonb_build_object(
      'cita_id', v_cita_id, 'orden', v_orden, 'nombre', v_asist_nombre
    ));
  end loop;

  return jsonb_build_object(
    'ok', true, 'grupo_id', v_grupo, 'cliente_id', v_cliente,
    'total', v_n, 'citas', v_result, 'inicio', p_inicio
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_profile_identity_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if current_setting('mecha.identity_ctx', true) = '1' then
    return new;
  end if;

  new.role                   := old.role;
  new.negocio_id             := old.negocio_id;
  new.plan                   := old.plan;
  new.ia_nivel               := old.ia_nivel;
  new.trial_ends_at          := old.trial_ends_at;
  new.stripe_customer_id     := old.stripe_customer_id;
  new.stripe_subscription_id := old.stripe_subscription_id;
  new.suscripcion_estado     := old.suscripcion_estado;
  new.periodo_fin            := old.periodo_fin;

  new.es_cuenta_demo         := old.es_cuenta_demo;
  new.cobro_manual           := old.cobro_manual;
  new.cobro_manual_previo    := old.cobro_manual_previo;
  new.cobro_manual_por       := old.cobro_manual_por;
  new.cobro_manual_en        := old.cobro_manual_en;
  new.cobro_manual_nota      := old.cobro_manual_nota;

  return new;
