CREATE OR REPLACE FUNCTION public.modificar_cita_publica(p_slug text, p_cita_id uuid, p_telefono text, p_nuevo_inicio timestamp with time zone, p_nuevo_profesional_id uuid DEFAULT NULL::uuid, p_canal text DEFAULT 'web'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_negocio    text;
  v_cita       record;
  v_prof       uuid;
  v_dur        int;
  v_espera     int;
  v_extra      int;
  v_total      int;
  v_min_ant    int;
  v_fin        timestamptz;
  v_fin_activa timestamptz;
  v_fin_espera timestamptz;
  v_tz         text := 'Europe/Madrid';
begin
  select negocio_id into v_negocio
  from public.negocio_portal
  where slug = p_slug and portal_activo = true;
  if v_negocio is null then raise exception 'Portal no disponible'; end if;

  if exists (select 1 from public.cierres_negocio cn
      where cn.negocio_id = v_negocio and cn.fecha = (p_nuevo_inicio at time zone v_tz)::date) then
    raise exception 'El salon esta cerrado ese dia';
  end if;

  select c.id, c.estado, c.inicio, c.servicio_id, c.profesional_id
    into v_cita
  from public.citas c
  join public.clientes cl on cl.id = c.cliente_id
  where c.id = p_cita_id and c.negocio_id = v_negocio
    and public.normalizar_telefono(cl.telefono) = public.normalizar_telefono(p_telefono);
  if v_cita.id is null then raise exception 'Cita no encontrada'; end if;
  if v_cita.estado not in ('pendiente','confirmada') then raise exception 'La cita no se puede modificar'; end if;
  if v_cita.inicio <= now() then raise exception 'La cita ya ha pasado'; end if;

  v_prof := coalesce(p_nuevo_profesional_id, v_cita.profesional_id);

  select duracion_activa_min, coalesce(duracion_espera_min,0), coalesce(duracion_activa_extra_min,0), coalesce(min_antelacion_min,0)
    into v_dur, v_espera, v_extra, v_min_ant
  from public.servicios
  where id = v_cita.servicio_id and negocio_id = v_negocio;
  if v_dur is null then raise exception 'Servicio no valido'; end if;

  if not exists (
    select 1 from public.profesionales
    where id = v_prof and negocio_id = v_negocio and activo = true
  ) then raise exception 'Profesional no valido'; end if;

  -- Override activo = false: ese profesional no realiza este servicio.
  if not public.profesional_ofrece_servicio(v_prof, v_cita.servicio_id) then
    raise exception 'Ese profesional no realiza este servicio';
  end if;

  -- Duracion efectiva: al cambiar de profesional el bloque se recalcula con SU duracion.
  select d.activa, d.espera, d.extra
    into v_dur, v_espera, v_extra
  from public.duracion_efectiva_profesional(v_cita.servicio_id, v_prof, v_dur, v_espera, v_extra) d;

  v_total      := v_dur + v_espera + v_extra;
  v_fin_activa := p_nuevo_inicio + make_interval(mins => v_dur);
  v_fin_espera := p_nuevo_inicio + make_interval(mins => v_dur + v_espera);
  v_fin        := p_nuevo_inicio + make_interval(mins => v_total);

  if p_nuevo_inicio < now() + make_interval(mins => greatest(v_min_ant, 0)) then
    raise exception 'Fuera de la antelacion minima';
  end if;

  if not exists (
    select 1 from public.horarios_profesional h
    where h.profesional_id = v_prof
      and h.dia_semana = extract(dow from (p_nuevo_inicio at time zone v_tz))::int
      and (p_nuevo_inicio at time zone v_tz)::time >= h.hora_inicio
      and (v_fin         at time zone v_tz)::time <= h.hora_fin
  ) then raise exception 'Fuera del horario laboral'; end if;

  if exists (
    select 1 from public.citas c
    cross join lateral public.ventanas_activas_cita(c.id, c.inicio, c.fin_activa, c.fin_espera, c.fin) v
    where c.profesional_id = v_prof
      and c.id <> p_cita_id
      and c.estado in ('pendiente','confirmada')
      and v.desde < v_fin
      and v.hasta > p_nuevo_inicio
  ) then raise exception 'El hueco ya esta ocupado'; end if;

  if exists (
    select 1 from public.bloqueos_profesional b
    where b.profesional_id = v_prof
      and b.inicio < v_fin and b.fin > p_nuevo_inicio
  ) then raise exception 'El profesional no esta disponible'; end if;

  update public.citas
    set inicio = p_nuevo_inicio,
        fin = v_fin,
        fin_activa = v_fin_activa,
        fin_espera = v_fin_espera,
        profesional_id = v_prof,
        confirmacion_enviada = false,
        recordatorio_enviado = false,
        modificado_at = now()
  where id = p_cita_id;

  return jsonb_build_object(
    'ok', true,
    'cita_id', p_cita_id,
    'inicio', p_nuevo_inicio,
    'fin', v_fin,
    'profesional_id', v_prof
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_cobro_online(p_pago_id uuid, p_metodo text DEFAULT 'online'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pago public.pagos;
  v_cab public.citas;
  v_prop int; v_desc int; v_metodo text;
  v_base_total int; v_n int; v_i int := 0;
  v_acc_total int := 0; v_acc_prop int := 0;
  v_share int; v_pshare int;
  v_first uuid := null; v_cobro uuid;
  v_precio numeric; v_nombre text; v_base int;
  r record;
begin
  select * into v_pago from public.pagos where id = p_pago_id;
  if not found then raise exception 'pago_no_encontrado'; end if;
  if v_pago.cita_id is null then return null; end if;

  select * into v_cab from public.citas where id = v_pago.cita_id;
  if not found then return null; end if;

  v_prop := greatest(0, coalesce((v_pago.metadata->>'propina_cents')::int, 0));
  v_desc := greatest(0, coalesce((v_pago.metadata->>'descuento_cents')::int, 0));
  v_metodo := coalesce(nullif(p_metodo, ''), v_pago.metadata->>'metodo', 'online');
  if v_metodo not in ('online','bizum') then v_metodo := 'online'; end if;

  if v_cab.grupo_id is null then
    if v_cab.cobrada then return v_cab.cobro_id; end if;
    select precio, nombre into v_precio, v_nombre from public.servicios where id = v_cab.servicio_id;
    v_base := coalesce(round(coalesce(v_precio,0)*100)::int, 0);
    insert into public.cobros (negocio_id, cita_id, grupo_id, profesional_id, cliente_id,
      total_cents, propina_cents, descuento_cents, metodo, efectivo_cents, datafono_cents, online_cents, origen, estado, idempotency_key)
    values (v_cab.negocio_id, v_cab.id, v_cab.grupo_id, v_cab.profesional_id, v_cab.cliente_id,
      v_pago.importe_cents, v_prop, v_desc, v_metodo, 0, 0, v_pago.importe_cents, 'portal', 'completado', 'pago:'||v_pago.id::text)
    returning id into v_cobro;
    insert into public.cobro_lineas (cobro_id, tipo, ref_id, nombre, precio_cents, cantidad)
    values (v_cobro, 'servicio', v_cab.servicio_id, coalesce(v_nombre,'Servicio'), v_base, 1);
    update public.citas set cobrada=true, cobro_id=v_cobro where id=v_cab.id and cobrada=false;
    return v_cobro;
  end if;

  -- GRUPO
  select coalesce(sum(round(coalesce(s.precio,0)*100)::int),0), count(*)
    into v_base_total, v_n
    from public.citas c left join public.servicios s on s.id=c.servicio_id
    where c.grupo_id = v_cab.grupo_id;

  for r in
    select c.id, c.profesional_id, c.cliente_id, c.negocio_id, c.servicio_id, c.cobrada,
           coalesce(round(coalesce(s.precio,0)*100)::int,0) as base, s.nombre
    from public.citas c left join public.servicios s on s.id=c.servicio_id
    where c.grupo_id = v_cab.grupo_id
    order by c.orden_en_grupo nulls first, c.inicio
  loop
    v_i := v_i + 1;
    if v_i < v_n then
      v_share  := case when v_base_total>0 then floor(v_pago.importe_cents::numeric * r.base / v_base_total)::int else 0 end;
      v_pshare := case when v_base_total>0 then floor(v_prop::numeric * r.base / v_base_total)::int else 0 end;
    else
      v_share  := v_pago.importe_cents - v_acc_total;
      v_pshare := v_prop - v_acc_prop;
    end if;
    v_acc_total := v_acc_total + v_share;
    v_acc_prop  := v_acc_prop + v_pshare;

    if r.cobrada then continue; end if;

    insert into public.cobros (negocio_id, cita_id, grupo_id, profesional_id, cliente_id,
      total_cents, propina_cents, descuento_cents, metodo, efectivo_cents, datafono_cents, online_cents, origen, estado, idempotency_key)
    values (r.negocio_id, r.id, v_cab.grupo_id, r.profesional_id, r.cliente_id,
      greatest(0, v_share), greatest(0, v_pshare), 0, v_metodo, 0, 0, greatest(0, v_share), 'portal', 'completado',
      'pago:'||v_pago.id::text||':'||r.id::text)
    returning id into v_cobro;
    insert into public.cobro_lineas (cobro_id, tipo, ref_id, nombre, precio_cents, cantidad)
    values (v_cobro, 'servicio', r.servicio_id, coalesce(r.nombre,'Servicio'), r.base, 1);
    update public.citas set cobrada=true, cobro_id=v_cobro where id=r.id and cobrada=false;
    if v_first is null then v_first := v_cobro; end if;
  end loop;

  return v_first;
end;
$function$

CREATE OR REPLACE FUNCTION public.requerir_senal_cita(p_cita_id uuid)
 RETURNS pagos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cita public.citas;
  v_cabecera uuid;
  v_total int;
  v_pago public.pagos;
begin
  select * into v_cita from public.citas where id = p_cita_id;
  if not found then raise exception 'cita_not_found'; end if;

  if auth.uid() is not null and v_cita.negocio_id is distinct from public.my_negocio_id_text() then
    raise exception 'cross_tenant';
  end if;

  if v_cita.grupo_id is not null then
    select coalesce(sum(public.importe_senal_servicio(c.servicio_id)), 0)
      into v_total
      from public.citas c where c.grupo_id = v_cita.grupo_id;
    select id into v_cabecera from public.citas
      where grupo_id = v_cita.grupo_id
      order by orden_en_grupo nulls first, inicio limit 1;
  else
    -- Cobra el deposito_importe ya calculado (client-aware). Sin importe pero con
    -- deposito_requerido -> senal plana del servicio. Sin deposito -> 0 (no cobra).
    if v_cita.deposito_importe is not null then
      v_total := round(v_cita.deposito_importe * 100)::int;
    elsif coalesce(v_cita.deposito_requerido, false) then
      v_total := public.importe_senal_servicio(v_cita.servicio_id);
    else
      v_total := 0;
    end if;
    v_cabecera := v_cita.id;
  end if;

  if coalesce(v_total, 0) <= 0 then
    return null;
  end if;

  select * into v_pago from public.pagos
    where cita_id = v_cabecera and tipo = 'senal' and estado = 'pendiente'
    limit 1;

  if found then
    update public.pagos set importe_cents = v_total, updated_at = now()
      where id = v_pago.id returning * into v_pago;
  else
    insert into public.pagos (negocio_id, cita_id, cliente_id, tipo, importe_cents, estado)
    values (v_cita.negocio_id, v_cabecera, v_cita.cliente_id, 'senal', v_total, 'pendiente')
    returning * into v_pago;
  end if;

  return v_pago;
end;
$function$

CREATE OR REPLACE FUNCTION public.vigilancia_bd_escritura_critica()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  hallazgos jsonb := '[]'::jsonb;
  rec         record;
  v_negocio    text;
  v_profesional uuid;
  v_servicio   uuid;
  v_error      text;
  v_detail     text;
  v_sqlstate   text;
  v_context    text;
BEGIN
  -- Prefiere la DEMO a proposito: es el escaparate publico y el tenant disennado
  -- para que se le toque. Si no existiera, cualquier tenant con servicio activo.
  SELECT negocio_id INTO v_negocio
  FROM public.servicios
  WHERE negocio_id = 'demo_salon_001' AND activo = true
  LIMIT 1;

  IF v_negocio IS NULL THEN
    SELECT negocio_id INTO v_negocio
    FROM public.servicios
    WHERE activo = true
    LIMIT 1;
  END IF;

  IF v_negocio IS NULL THEN
    RETURN jsonb_build_array(jsonb_build_object(
      'tipo', 'sin-datos-para-probar', 'nivel', 'aviso', 'ambito', 'base-de-datos',
      'titulo', 'Escritura critica sin probar: no hay ningun servicio activo',
      'detalle', 'No hay ningun servicio activo en la base para construir la cita de prueba.'
    ));
  END IF;

  SELECT id INTO v_profesional
  FROM public.profesionales WHERE negocio_id = v_negocio AND activo = true LIMIT 1;
  SELECT id INTO v_servicio
  FROM public.servicios WHERE negocio_id = v_negocio AND activo = true LIMIT 1;

  IF v_profesional IS NULL OR v_servicio IS NULL THEN
    RETURN jsonb_build_array(jsonb_build_object(
      'tipo', 'sin-datos-para-probar', 'nivel', 'aviso', 'ambito', 'base-de-datos',
      'titulo', 'Escritura critica sin probar: falta profesional o servicio activo',
      'detalle', format('El negocio %s no tiene profesional o servicio activo para construir la cita de prueba.', v_negocio)
    ));
  END IF;

  -- ---- PRUEBA 1: INSERT directo en citas ----
  -- 400 dias en el futuro para no chocar con nada real; canal 'web' y estado
  -- 'pendiente' son valores validos de los CHECK de la tabla.
  BEGIN
    INSERT INTO public.citas (
      negocio_id, profesional_id, servicio_id,
      inicio, fin, estado, canal
    ) VALUES (
      v_negocio, v_profesional, v_servicio,
      now() + interval '400 days',
      now() + interval '400 days' + interval '30 minutes',
      'pendiente', 'web'
    );
    -- Exito: forzar rollback de la subtransaccion (BEGIN/EXCEPTION no tiene
    -- "rollback on success", asi que se provoca a proposito y se atrapa).
    RAISE EXCEPTION USING ERRCODE = 'VG001';
  EXCEPTION
    WHEN SQLSTATE 'VG001' THEN
      -- INSERT funciono y todos los triggers se dispararon sin error. Todo bien.
      NULL;
    WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS
        v_sqlstate = RETURNED_SQLSTATE,
        v_error    = MESSAGE_TEXT,
        v_detail   = PG_EXCEPTION_DETAIL,
        v_context  = PG_EXCEPTION_CONTEXT;
      hallazgos := hallazgos || jsonb_build_object(
        'tipo',     'escritura-cita-rota',
        'nivel', 'bloqueante', 'ambito', 'base-de-datos',
        'sqlstate', v_sqlstate,
        'error',    v_error,
        'titulo',   format('INSERT INTO citas falla con %s: no se puede crear NINGUNA cita', v_sqlstate),
        'detalle',  format(
          'INSERT INTO citas falla con %s: %s. Detalle: %s. Contexto: %s. Esto tumba el alta ' ||
          'de citas en TODOS los canales (agenda, portal publico, WhatsApp, agente de voz). ' ||
          'Casi siempre es un trigger que referencia una columna que no existe.',
          v_sqlstate, v_error,
          coalesce(v_detail, '(sin detalle)'),
          coalesce(left(v_context, 300), '(sin contexto)')
        )
      );
  END;

  -- ---- PRUEBA 2: las RPC del portal publico concedidas a anon ----
  -- La otra mitad del 30 ago: la firma recreada no llevaba grant a anon y el
  -- portal no podia reservar aunque la logica estuviera bien.
  FOR rec IN
    SELECT f.rpc,
           EXISTS (
             SELECT 1 FROM pg_proc p
             JOIN pg_namespace ns ON p.pronamespace = ns.oid
             WHERE ns.nspname = 'public' AND p.proname = f.rpc
               AND has_function_privilege('anon', p.oid, 'execute')
           ) AS anon_puede
    FROM unnest(array['crear_cita_publica', 'portal_info', 'disponibilidad_publica']) AS f(rpc)
  LOOP
    IF NOT rec.anon_puede THEN
      hallazgos := hallazgos || jsonb_build_object(
        'tipo',    'rpc-sin-grant-anon',
        'nivel', 'bloqueante', 'ambito', 'base-de-datos',
        'funcion', rec.rpc,
        'titulo',  format('public.%s no tiene GRANT EXECUTE a anon: el portal publico roto', rec.rpc),
        'detalle', format(
          '%s no es ejecutable por anon en ninguna de sus firmas. El portal publico (/r/<slug>) ' ||
          'llama a esta RPC sin sesion: sin el grant, reservar rompe con 403/404 aunque la ' ||
          'logica de la funcion este perfecta. Desde el round 4 de seguridad los grants a anon ' ||
          'son explicitos: toda recreacion de la funcion tiene que repetir el grant.',
          rec.rpc
        )
      );
    END IF;
  END LOOP;

  RETURN hallazgos;
END;
$function$
